export function encodeRegisterBatch(request_id: RequestId, body: RegisterBatchBody): Uint8Array {
  exactInputFields(body, RegisterBatchBody_INPUT_FIELDS, BATCH_INVALID_BODY);
  const label = body.label;
  return encodeBatchRequest(request_id, BATCH_REGISTER_BATCH_REQUEST_KIND, [
    ["batch_id", {kind: "string", value: refuse(BATCH_INVALID_FIELD, () => BatchId(body.batch_id))}],
    ["concurrency", encodeBatchConcurrency(body.concurrency)],
    ["label", label === null
        ? {kind: "null"}
        : {kind: "string", value: refuse(BATCH_INVALID_FIELD, () => BatchLabel(label))}],
    ["members", {
        kind: "array",
        items: boundedItems(body.members, MAX_BATCH_CONTROL_MEMBERS, BATCH_MEMBERSHIP_TOO_LARGE, BATCH_EMPTY_BATCH).map(
          (value): JsonValue => ({kind: "string", value: refuse(BATCH_INVALID_FIELD, () => BatchMemberKey(value))}),
        ),
      }],
  ]);
}

/** Command kinds this protocol version defines that no builder above produces. A client needing one of these builds it by hand or waits for the generator to describe it. */
export const BATCH_REQUEST_KINDS_NOT_GENERATED: readonly string[] = [
];

/** One batch, its whole membership, and what that membership rolls up to. The rolled-up state is never stored: the durable registry has no such column, because the rollup is a total function of the member states and a column would be a second copy of an answer that can drift. It travels here because the members that justify it travel beside it — and the Rust decoder re-derives it and refuses a body whose carried state contradicts its own members, which is a relation between two fields and therefore one this file does not hold. */
export const BATCH_BATCH_DETAIL_RESULT_RESPONSE_KIND = "batch_detail_result";
export interface BatchDetailView {
  readonly batch: BatchRecord;
  readonly members: readonly BatchMemberRecord[];
  readonly request_id: RequestId;
  readonly state: BatchState;
}

/** The exact key set this response's wire body carries; the correlation identifier is not among them, because it travels in the envelope. */
export const BatchDetailView_BODY_FIELDS: readonly string[] = [
  "batch",
  "members",
  "state",
];

export function decodeBatchDetailView(request_id: RequestId, body: JsonValue): BatchDetailView {
  const fields = exactFields(body, BatchDetailView_BODY_FIELDS, BATCH_INVALID_BODY);
  return {
    batch: decodeBatchRecord(bodyValue(fields, "batch", BATCH_INVALID_BODY)),
    members: bodyArray(fields, "members", BATCH_INVALID_BODY, MAX_BATCH_CONTROL_MEMBERS, BATCH_MEMBERSHIP_TOO_LARGE).map(
      decodeBatchMemberRecord,
    ),
    request_id: request_id,
    state: refuse(BATCH_UNKNOWN_ENUM_VALUE, () => decodeBatchState(bodyString(fields, "state", BATCH_INVALID_BODY))),
  };
}

/** One bounded page of batch rows, in registration order. `more` is carried explicitly rather than inferred from a short page: a short page is not the same statement as a last page, and a client that inferred `done` from one would stop early. */
export const BATCH_BATCH_LIST_RESULT_RESPONSE_KIND = "batch_list_result";
export interface BatchListPage {
  readonly batches: readonly BatchRecord[];
  readonly more: boolean;
  readonly next_cursor: BatchCursor | null;
  readonly request_id: RequestId;
}

/** The exact key set this response's wire body carries; the correlation identifier is not among them, because it travels in the envelope. */
export const BatchListPage_BODY_FIELDS: readonly string[] = [
  "batches",
  "more",
  "next_cursor",
];

export function decodeBatchListPage(request_id: RequestId, body: JsonValue): BatchListPage {
  const fields = exactFields(body, BatchListPage_BODY_FIELDS, BATCH_INVALID_BODY);
  return {
    batches: bodyArray(fields, "batches", BATCH_INVALID_BODY, MAX_BATCH_PAGE_ITEMS, BATCH_PAGE_TOO_LARGE).map(
      decodeBatchRecord,
    ),
    more: bodyBool(fields, "more", BATCH_INVALID_BODY),
    next_cursor: mapNullable(bodyIntegerOrNull(fields, "next_cursor", BATCH_INVALID_BODY), (value) =>
      refuse(BATCH_INVALID_BODY, () => BatchCursor(value)),
    ),
    request_id: request_id,
  };
}

/** One batch and its whole membership are durable. `accepted` rather than `completed`: the rows are committed, and what they record has not taken effect and cannot, because registering a batch submits nothing. Every member was written `unsubmitted`, at ordinals `0..member_count`. */
export const BATCH_BATCH_REGISTERED_RESPONSE_KIND = "batch_registered";
export interface BatchReceipt {
  readonly batch_id: BatchId;
  readonly created_at_ms: EpochMillis;
  readonly entry_id: DurableRowId;
  readonly member_count: MemberCount;
  readonly request_id: RequestId;
  readonly revision: BatchRevision;
}

/** The exact key set this response's wire body carries; the correlation identifier is not among them, because it travels in the envelope. */
export const BatchReceipt_BODY_FIELDS: readonly string[] = [
  "batch_id",
  "created_at_ms",
  "entry_id",
  "member_count",
  "revision",
];

export function decodeBatchReceipt(request_id: RequestId, body: JsonValue): BatchReceipt {
  const fields = exactFields(body, BatchReceipt_BODY_FIELDS, BATCH_INVALID_BODY);
  return {
    batch_id: refuse(BATCH_INVALID_FIELD, () => BatchId(bodyString(fields, "batch_id", BATCH_INVALID_BODY))),
    created_at_ms: refuse(BATCH_TIME_BEFORE_EPOCH, () => EpochMillis(bodyInteger(fields, "created_at_ms", BATCH_INVALID_BODY))),
    entry_id: refuse(BATCH_UNWRITTEN_ROW, () => DurableRowId(bodyUnsigned(fields, "entry_id", BATCH_INVALID_BODY))),
    member_count: rangedInteger(
      bodyUnsigned(fields, "member_count", BATCH_INVALID_BODY),
      MemberCount_MIN,
      BATCH_EMPTY_BATCH,
      BATCH_MEMBERSHIP_TOO_LARGE,
      MemberCount,
    ),
    request_id: request_id,
    revision: refuse(BATCH_UNWRITTEN_REVISION, () => BatchRevision(bodyUnsigned(fields, "revision", BATCH_INVALID_BODY))),
  };
}

/** One member's row moved. The revision is the fencing value the *next* advance of this member must expect, and it is at least two: registration is the only writer of revision one, so an advance receipt below that names a row no accepted advance could have left behind. */
export const BATCH_MEMBER_ADVANCED_RESPONSE_KIND = "member_advanced";
export interface MemberReceipt {
  readonly batch_id: BatchId;
  readonly last_sequence: LastSequence;
  readonly member_key: BatchMemberKey;
  readonly ordinal: MemberOrdinal;
  readonly request_id: RequestId;
  readonly revision: AdvancedRevision;
  readonly state: MemberProgress;
  readonly updated_at_ms: EpochMillis;
}

/** The exact key set this response's wire body carries; the correlation identifier is not among them, because it travels in the envelope. */
export const MemberReceipt_BODY_FIELDS: readonly string[] = [
  "batch_id",
  "last_sequence",
  "member_key",
  "ordinal",
  "revision",
  "state",
  "updated_at_ms",
];

export function decodeMemberReceipt(request_id: RequestId, body: JsonValue): MemberReceipt {
  const fields = exactFields(body, MemberReceipt_BODY_FIELDS, BATCH_INVALID_BODY);
  return {
    batch_id: refuse(BATCH_INVALID_FIELD, () => BatchId(bodyString(fields, "batch_id", BATCH_INVALID_BODY))),
    last_sequence: refuse(BATCH_INVALID_BODY, () => LastSequence(bodyUnsigned(fields, "last_sequence", BATCH_INVALID_BODY))),
    member_key: refuse(BATCH_INVALID_FIELD, () => BatchMemberKey(bodyString(fields, "member_key", BATCH_INVALID_BODY))),
    ordinal: refuse(BATCH_MEMBERS_OUT_OF_ORDER, () => MemberOrdinal(bodyUnsigned(fields, "ordinal", BATCH_INVALID_BODY))),
    request_id: request_id,
    revision: refuse(BATCH_NOT_AN_ADVANCE, () => AdvancedRevision(bodyUnsigned(fields, "revision", BATCH_INVALID_BODY))),
    state: refuse(BATCH_UNKNOWN_ENUM_VALUE, () => decodeMemberProgress(bodyString(fields, "state", BATCH_INVALID_BODY))),
    updated_at_ms: refuse(BATCH_TIME_BEFORE_EPOCH, () => EpochMillis(bodyInteger(fields, "updated_at_ms", BATCH_INVALID_BODY))),
  };
}

/** The operation was refused. Nothing was written and nothing was read. A stale expected revision is deliberately not among these words: that is a conflict, which a caller retries against the durable revision the answer carries, where a refusal is not retried at all until the request changes. */
export const BATCH_REFUSED_RESPONSE_KIND = "refused";
export interface BatchRefused {
  readonly refusal: BatchRefusal;
  readonly request_id: RequestId;
}

/** The exact key set this response's wire body carries; the correlation identifier is not among them, because it travels in the envelope. */
export const BatchRefused_BODY_FIELDS: readonly string[] = [
  "refusal",
];

export function decodeBatchRefused(request_id: RequestId, body: JsonValue): BatchRefused {
  const fields = exactFields(body, BatchRefused_BODY_FIELDS, BATCH_INVALID_BODY);
  return {
    refusal: refuse(BATCH_UNKNOWN_ENUM_VALUE, () => decodeBatchRefusal(bodyString(fields, "refusal", BATCH_INVALID_BODY))),
    request_id: request_id,
  };
}

/** The caller's expected revision did not match the durable one and nothing was written. Retry against `durable_revision`. Two revisions that agree would be agreement rather than a conflict, and the Rust constructor refuses to answer one — a relation between two fields, and therefore not a rule this file holds. */
export const BATCH_REVISION_CONFLICT_RESPONSE_KIND = "revision_conflict";
export interface BatchRevisionConflict {
  readonly durable_revision: BatchRevision;
  readonly expected_revision: BatchRevision;
  readonly request_id: RequestId;
}

/** The exact key set this response's wire body carries; the correlation identifier is not among them, because it travels in the envelope. */
export const BatchRevisionConflict_BODY_FIELDS: readonly string[] = [
  "durable_revision",
  "expected_revision",
];

export function decodeBatchRevisionConflict(request_id: RequestId, body: JsonValue): BatchRevisionConflict {
  const fields = exactFields(body, BatchRevisionConflict_BODY_FIELDS, BATCH_INVALID_BODY);
  return {
    durable_revision: refuse(BATCH_UNWRITTEN_REVISION, () => BatchRevision(bodyUnsigned(fields, "durable_revision", BATCH_INVALID_BODY))),
    expected_revision: refuse(BATCH_UNWRITTEN_REVISION, () => BatchRevision(bodyUnsigned(fields, "expected_revision", BATCH_INVALID_BODY))),
    request_id: request_id,
  };
}

/**
 * Kinds this protocol version defines that this file does not decode.
 *
 * They are neither refused nor guessed at: a peer that sent one sent something
 * defined, and a client told otherwise might act on the lie. The body is not
 * handed back, because nothing here has validated it.
 */
export const BATCH_RESPONSE_KINDS_NOT_DECODED = [] as const;
export type UndecodedBatchResponseKind = (typeof BATCH_RESPONSE_KINDS_NOT_DECODED)[number];
export function isUndecodedBatchResponseKind(value: string): value is UndecodedBatchResponseKind {
  return (BATCH_RESPONSE_KINDS_NOT_DECODED as readonly string[]).includes(value);
}

/** Every response this file can hand a caller. */
export type BatchResponse =
  | {readonly kind: "batch_detail_result"; readonly value: BatchDetailView}
  | {readonly kind: "batch_list_result"; readonly value: BatchListPage}
  | {readonly kind: "batch_registered"; readonly value: BatchReceipt}
  | {readonly kind: "member_advanced"; readonly value: MemberReceipt}
  | {readonly kind: "refused"; readonly value: BatchRefused}
  | {readonly kind: "revision_conflict"; readonly value: BatchRevisionConflict}
  | {readonly kind: "undecoded"; readonly request_id: RequestId; readonly response_kind: UndecodedBatchResponseKind};

export function assertNeverBatchResponse(value: never): never {
  throw new ValidationError("BatchResponse", `unhandled variant: ${JSON.stringify(value)}`);
}

/**
 * Decode one canonical response payload.
 *
 * The payload is the framed transport's payload, without its length prefix.
 * The envelope is admitted first and on both axes: a name this file does not
 * implement and a major version outside its range are different refusals, and
 * neither is downgraded into the other.
 */
export function decodeBatchResponse(payload: Uint8Array): BatchResponse {
  if (payload.length > MAX_BATCH_CONTROL_CANONICAL_BYTES) {
    throw new RefusalError(
      BATCH_FRAME_SIZE,
      `canonical payload is ${payload.length} bytes; maximum is ${MAX_BATCH_CONTROL_CANONICAL_BYTES}`,
    );
  }
  const message = decodeMessageAdmitted(payload, [
    {protocol: BATCH_CONTROL_PROTOCOL, minVersion: BATCH_PROTOCOL_VERSION, maxVersion: BATCH_PROTOCOL_VERSION},
  ]);
  const request_id = refuseField(BATCH_FIELD_INVALID, BATCH_FIELD_GRAMMAR, () =>
    RequestId(message.envelope.requestId),
  );
  const kind = message.envelope.kind;
  if (isUndecodedBatchResponseKind(kind)) {
    return {kind: "undecoded", request_id, response_kind: kind};
  }
  switch (kind) {
    case BATCH_BATCH_DETAIL_RESULT_RESPONSE_KIND:
      return {kind: BATCH_BATCH_DETAIL_RESULT_RESPONSE_KIND, value: decodeBatchDetailView(request_id, message.body)};
    case BATCH_BATCH_LIST_RESULT_RESPONSE_KIND:
      return {kind: BATCH_BATCH_LIST_RESULT_RESPONSE_KIND, value: decodeBatchListPage(request_id, message.body)};
    case BATCH_BATCH_REGISTERED_RESPONSE_KIND:
      return {kind: BATCH_BATCH_REGISTERED_RESPONSE_KIND, value: decodeBatchReceipt(request_id, message.body)};
    case BATCH_MEMBER_ADVANCED_RESPONSE_KIND:
      return {kind: BATCH_MEMBER_ADVANCED_RESPONSE_KIND, value: decodeMemberReceipt(request_id, message.body)};
    case BATCH_REFUSED_RESPONSE_KIND:
      return {kind: BATCH_REFUSED_RESPONSE_KIND, value: decodeBatchRefused(request_id, message.body)};
    case BATCH_REVISION_CONFLICT_RESPONSE_KIND:
      return {kind: BATCH_REVISION_CONFLICT_RESPONSE_KIND, value: decodeBatchRevisionConflict(request_id, message.body)};
    default:
      throw new RefusalError(
        BATCH_UNKNOWN_KIND,
        "message kind is not defined by this protocol version",
      );
  }
}
